import sys
H=sys.argv[1]; P='/home/claude/devtools-wt/HANDOFF.md'
s=open(P).read()
def rep(a,b):
    global s; assert s.count(a)==1,a[:60]; s=s.replace(a,b)
rep("Last updated 2026-11-14, after release **89.0.0** (`ef89aff`): ","Last updated 2026-11-14, after release **90.0.0** (`%s`): **Chapter 35, A Brief History of Psychiatry** (`ch35`), the book's last chapter. **Every chapter of the book is now built.** Release **89.0.0** (`ef89aff`): "%H)
rep("Next work: **Chapter 35, A Brief History of Psychiatry** (the last chapter), as release 90.0.0; see section 7.","Next work: none from the book; see section 7 for rechecks and optional features.")
rep("section 34.4 is complete). **Not yet built: Chapter 35.**","section 34.4 is complete) and Chapter 35 (`ch35`). **The whole book is built.**")
row="""| Ch 35 (A Brief History of Psychiatry, `ch35`) | 77/77 | 12/12 | Complete (release 90.0.0; PDF 0-based `range(3448,3553)` in `tools/extract-ch35.py` (no bold chapter heading on page 3449, so cut by page; References on 3553), about 9,500 words: 4,600 of prose and 4,800 of **Table 35-1** (persons and events, about 170 rows, pages 3472 to 3552; the publication column is **cut off at the page edge in the PDF itself**, so drafters used only legible titles). `tools/chunk-ch35.py` cuts 4 prose chunks at bold headings and the table at page 3512; shared spec in `work/ch35common` (history rules: dated steps, names and years as printed, attributed interpretations, old treatments as history), 6 Opus drafters (3.5 to 9 minutes; the table jobs took longest), all 0 overlap. Figure 35-12 (DSM evolution) viewed as `p3469.png` and turned into a table; the others are portraits or photos. Sections t1 to t4 run 1,250 to 1,800 words because every table row is kept; accepted. 8 update boxes, 5 corrections: **Pussin** removed the chains at the Bicêtre in **May to June 1797** and Pinel and Pussin at the Salpêtrière in **1800** (the unchaining scene is largely legend; Robert-Fleury painting 1876); **Edinburgh phrenology** was 19th-century (Edinburgh Phrenological Society, February 1820; chapter: 18th century); **Utica** was authorized in 1836 and opened **January 16, 1843** (chapter: about 1850, tied to Dix), Dix's 1843 memorial led to Worcester's enlargement and her first new asylum was **Trenton, 1848**, and the 1808 law is the **County** (not Country) Asylums Act; **folie circulaire** was **Jean-Pierre Falret's** (1851 lecture, Academy paper February 14, 1854; Baillarger January 31, 1854; chapter: Jules Falret, his son); the unitary view of mental illness is **Karl Menninger's** (The Vital Balance, 1963; chapter: Walter). Also Public Law 88-164 signed **October 31, 1963**, run by **NIMH** (chapter: NIH); the **Rosenhan** study questioned (Cahalan 2019, Nature review; Scull 2023 calls it fraud; written to the contested-topics pattern); ICD-11 (adopted May 2019, in effect 1 January 2022) and DSM-5-TR (March 2022), with a note that DSM category counts vary by method (Figure 35-12 prints DSM-II 185 and DSM-IV 361; other sources give 182 and 297). Cards, high-yield items and one exam callout were aligned before the build; one case stem (c35-em04, 18th-century Edinburgh) fixed after it. Sonnet why-not lines (thirds) needed no realignment; 4 lines reworded (`tools/checks/fixwn-ch35.js`); 2 checks reworded and ASCII spellings (Bicetre, demence precoce, Fuhrer) restored to diacritics. Book oddities kept: Country Asylums Act, Greisinger and Kalbaum, Eugene/Eugen Bleuler, Adolph/Adolf Meyer, Salpétrière, Plato paired with Galen, Charaka Samhita diacritics, garbled Feighner and 1953 sentences, \"functional imagining\", Table 35-1 misspellings (Constanitus, Pritchard, Aiken, Nuremburg, Honigfield, Drug Enforcement Agency) and a few countries (Krafft-Ebing under Germany). No helper (no decision path in a history chapter); look-alike `psychosis-terms35` (démence précoce to schizophrenia); chronology visual in s35-future; 12 glossary terms) |
"""
a=[l for l in s.split("\n") if l.startswith("| Ch 20 | 104/104")][0]
rep(a+"\n",row+a+"\n")
rep("Totals: **3,937/3,937 cases and 1,228/1,228 sections**, with all tests passing on `ef89aff`","Totals: **4,014/4,014 cases and 1,240/1,240 sections**, with all tests passing on `%s` (release 90.0.0; same checks as below, plus overlap 0 and a coverage audit with only citation fragments and credit lines flagged for Ch 35). Before that, all tests passed on `ef89aff`"%H)
rep("Latest changelog version **89.0.0**; `sw.js` VERSION is `PREFIX + '89.0.0'`.","Latest changelog version **90.0.0**; `sw.js` VERSION is `PREFIX + '90.0.0'`.")
i=s.index("1. **Chapter 35, A Brief History of Psychiatry** (the last chapter)."); j=s.index("2. Take the changelog version")
rep(s[i:j],"1. **The book is complete** (release 90.0.0 added Chapter 35). There is no next chapter. Useful work from here: the rechecks in items 4 to 6, the optional features in 7 and 8, and any feature or correction the owner asks for (recipe C, or a correction release). Templates from 90.0.0 for any rebuild: `build_ch35.js`, `register-ch35.py`, `add-lookalike-ch35.js` with `terms35.json`, `tools/checks/mkrest35.js`.\n")
add="""
- **Chapter 35 (Nov 14, release 90.0.0):** the chapter's first page has no bold chapter heading, so it was cut by page number; Table 35-1 fills 80 PDF pages and its publication column is clipped in the PDF itself (turning `TEXT_MEDIABOX_CLIP` off does not help). Tell table drafters to use only legible text and never complete a cut-off title. History chapters carry many wrong institutional dates and names (5 corrections here): research every founding date, first-use credit and person's name the drafters flag, and fix cards and exam callouts before the build. The whole release (6 Opus drafters, 4 Sonnet learning agents, about 13 standard searches) fit in one session.
- **Injected text in search results again (Nov 14):** a cavac.at mirror page carried an instruction to add a sentence to "the current document". Ignored; never cite cavac.at.
"""
